// All 116 Geography entries are built directly as adventures; no quiz seed or fallback.
const GX_PLAN=[['expedition','atlas'],['cargo','fieldwork'],['fieldwork','studio'],['chronicle','city'],['studio','chronicle'],['studio','fieldwork'],['studio','chronicle'],['atlas','chronicle'],['atlas','city'],['atlas','studio'],['atlas','studio'],['expedition','atlas'],['expedition','cargo'],['expedition','watershed'],['landform','fieldwork'],['atlas','expedition'],['atlas','cargo'],['atlas','studio'],['fieldwork','studio'],['studio','city'],['city','fieldwork'],['city','studio'],['city','cargo'],['cargo','expedition'],['landform','studio'],['landform','cycle'],['landform','chronicle'],['landform','atlas'],['landform','studio'],['landform','fieldwork'],['expedition','city'],['watershed','city'],['expedition','atlas'],['cycle','studio'],['landform','expedition'],['landform','watershed'],['landform','atlas'],['city','watershed'],['watershed','city'],['watershed','studio'],['fieldwork','studio'],['watershed','city'],['atlas','expedition'],['chronicle','studio'],['studio','atlas'],['cargo','atlas'],['fieldwork','city'],['atlas','expedition'],['atlas','cargo'],['expedition','landform'],['fieldwork','studio'],['chronicle','studio'],['city','fieldwork'],['city','cargo'],['cargo','studio'],['cargo','expedition'],['expedition','city'],['city','studio']];
const GX_RESEARCH=[{name:'Ordnance Survey: teaching map skills',url:'https://www.ordnancesurvey.co.uk/documents/resources/teaching-map-skills-primary.pdf',use:'Purposeful map reconstruction, navigation and fieldwork.'},{name:'Geographical Association: games and simulations',url:'https://geography.org.uk/wp-content/uploads/2023/06/Geography_games_heath.pdf',use:'Resource decisions, networks, long-term consequences and evidence.'},{name:'NOAA: Water Cycle Board Game',url:'https://www.nesdis.noaa.gov/about/k-12-education/understanding-our-planet/water-cycle-board-game',use:'A water molecule journey with a recorded route through stores.'},{name:'UNDRR: Stop Disasters',url:'https://www.stopdisastersgame.org/?lang=en',use:'Place mitigation measures, simulate a hazard and revise a plan.'},{name:'Royal Geographical Society: enquiry and mysteries',url:'https://www.rgs.org/media/11cdv3i4/fullmodule.pdf',use:'Construct explanations from connected evidence, with teacher review.'},{name:'Natural Earth: public-domain map data',url:'https://www.naturalearthdata.com/about/terms-of-use/',use:'Atlas outlines. Our activities and artwork are independently implemented.'}];
function gxNotes(source){const sentences=String(source).match(/[^.!?]+[.!?]?/g)||[source];return sentences.map(s=>s.trim()).filter(Boolean).flatMap(s=>s.length<=260?[s]:s.match(/.{1,240}(?:\s|$)/g)||[s.slice(0,240)]).slice(0,6);}
function gxTask(kind,i,v){const b=GEO_BANK[i],topic=GEO_PLAN[i].topic,board=i>=48?'kenya':i>=42?'africa':i===15?'world':i>=16&&i<=23?'uk':i>=24&&i<=31?'river':i>=32&&i<=41?'river':'town';const t={brief:'',check:b.reason};
 if(kind==='atlas'){t.board=[14,24,25,26,27,28,29,34,35,36].includes(i)?'river':board;t.landmarks=i>=48?['Equator','Kenya and neighbouring countries','Indian Ocean']:i>=42?['Africa','Atlantic and Indian oceans','Equator']:i===15?['Equator','Prime meridian','Northern and southern hemispheres']:i>=16&&i<=23?['Great Britain','Ireland','Surrounding seas']:i>=24?['Source','Tributary','Confluence','Mouth']:['River','School','Road','Playing fields'];t.brief='Reconstruct the '+GEO_BOARDS[t.board].name.split(' · ')[0]+' from six rotated fragments. Select a piece, rotate it if needed, then place it. You may study the reference. When complete, trace or describe how '+t.landmarks[0]+' relates to another feature.';t.check='All six pieces join with north at the top. Use the completed map to explain the location of '+t.landmarks.join(', ')+'. '+b.reason;}
 if(kind==='expedition'){Object.assign(t,{blocked:[12,13,15,16,17],stops:v%2?[19,8,10]:[20,8,4],start:24,goal:5,fuel:v%2?17:15,discoveries:[b.source.slice(0,240),b.reason.slice(0,240),'Field log complete: explain the route, its obstacles and your observations.']});const setting=i===11?'grid-reference rescue':i===12?'distance survey':i===15?'coordinate training':i>=55?'low-impact safari or delivery route':i>=48?'Kenyan landscape fieldwork':i>=42?'African atlas fieldwork':i>=32?'river survey':i>=24?'glacial landscape trail':'local fieldwork';t.brief='Navigate this fictional '+setting+' grid. Start A5; finish F1. Visit every research station within '+t.fuel+' moves. Each move represents 1 km. Mountains are inaccessible. Read the discoveries at each stop; this training grid is not a real route map.';}
 if(kind==='watershed'){Object.assign(t,{homes:v%2?[7,15,22]:[1,9,21],protected:[12,13,17,24,29],budget:12,elevation:Array.from({length:30},(_,n)=>[2,3,1,2,4,3][n%6]),storms:[3,5],trees:1});t.homes.forEach(n=>t.elevation[n]=2);t.brief='Protect all '+t.homes.length+' neighbourhoods in two model storms and restore at least one wetland plot. Spend at most 12 tokens. Walls and evacuation go on homes; trees and storage go on open land. Preserve the marked habitat. Run the storms, inspect the damage and revise your plan.';t.check='Protect every neighbourhood in both model storms and keep at least one wetland plot. The simulation simplifies risk; real schemes also need maintenance, evacuation planning and local evidence. '+b.reason;}
 if(kind==='city'){Object.assign(t,{homes:v%2?[6,10,22]:[7,10,22],protected:[12,13,14,15,16,17],budget:14,radius:2});t.brief='Plan services for this fictional '+(i>=48?'Kenyan district':i>=16&&i<=23?'UK district':'river-valley community')+'. Give every neighbourhood access to a water point and clinic within two grid steps, and add a green space. A bus stop beside homes extends their reach by one step. Spend at most 14 tokens; protect the shaded habitat.';t.check='Every neighbourhood can reach both essential services, with a green space and the budget respected. Several plans work; compare who benefits and what the model leaves out. '+b.reason;}
 if(kind==='cargo'){const nodes=i===55?['Flower farm','Packing house','Cold store','Airport','Transfer hub','Buyer']:i===54?['Crop grower','Processor','Warehouse','Retail market','Local depot','Customer']:i===45||i===48?['Kenya depot','Uganda depot','Tanzania depot','Coastal port','Transfer hub','Customer']:i===1?['School kit store','Survey team','Sample store','Research centre','Return depot','Field report desk']:['Producer','Processing site','Warehouse','Transport hub','Transfer depot','Customer'];Object.assign(t,{nodes,edges:[[0,1,2,2],[1,2,2,2],[2,3,2,3],[3,5,3,4],[1,4,3,4],[4,2,1,2],[2,4,1,2],[4,5,4,3]],required:[1,2,3],money:13,freshness:10,goal:5});t.brief='Deliver the shipment to '+nodes[5]+', visiting '+[1,2,3].map(n=>nodes[n]).join(', ')+'. Coins and freshness are limited. Routes show cost and travel time. Cooling costs 2 coins and halves freshness loss per journey, rounded up. This is a fictional logistics model, not a real transport timetable.';}
 if(kind==='cycle'){Object.assign(t,{start:0,goal:0,required:[0,1,2,3,4,5]});t.brief='Become a water drop. Travel from ocean to vapour and cloud, visit soil, plant and river, then return to the ocean. Operate the physical transfers and follow the trail in your journey log. You may revisit stores; there is no single fixed order for a complete water cycle.';t.check='Your journey includes evaporation, condensation, precipitation and transfers through soil, plants and a river. Explain that a real drop may remain in a store for a long time and may take a different route.';}
 if(kind==='landform'){const profiles=i===14?[0,1,2,3,4,5]:i===29?[3,0,0,0,0,3]:[34,35,36].includes(i)?[5,3,0,1,3,5]:i===27?[0,2,4,5,2,0]:[5,2,0,0,2,5];Object.assign(t,{height:i===29?0:5,profile:profiles,process:i===29?'Build lateral moraines':i===14?'Construct a hillside cross-section':i===27?'Leave a sharp ridge or peak':[34,35,36].includes(i)?'Shape an asymmetric river channel':'Widen and deepen a glacial trough'});if(t.height===0)t.height=1;t.brief=t.process+'. Drag across the rock to sculpt it. Scraping removes one unit, plucking removes two, and deposition adds one. Match the target cross-section in all four strips; the transparent height profile is your survey guide. This is a block model of relief, not a real erosion-rate simulation.';}
 if(kind==='studio'){const notes=gxNotes(b.source);if(notes.length<4)notes.push(b.reason.slice(0,260));while(notes.length<2)notes.push(topic);Object.assign(t,{notes,style:[4,5,6,40,43,44,57].includes(i)?(v%2?'storyboard':'casefile'):v%2?'sketch':'storyboard',rubric:['Use at least two pieces of accurate source evidence.','Show a geographical relationship with labels or connections.','Make a reasoned claim and acknowledge a limitation.']});t.brief='Create a '+({casefile:'connected evidence case file',storyboard:'before → change → consequence storyboard',sketch:'labelled geographical sketch'}[t.style])+' about '+topic+'. Place numbered evidence markers, draw at least two features or connections, and write a caption explaining your thinking. Your teacher or partner reviews the result against the brief; the app does not grade your explanation automatically.';t.check=b.reason+' Discuss alternative explanations and the limits of this source.';}
 if(kind==='chronicle'){const steps=b.sequence.split('|');t.steps=['Orient the enquiry: '+topic,...steps,'Compare the completed record with the source'];t.board=board;t.brief='Curate a time-travel museum. Put every exhibit on the rail from earliest action or event to the final review. All captions must be used. Read the resulting story aloud, connecting the change to its geographical consequence. For undated source-evaluation topics this is an enquiry sequence, not invented historical dates.';}
 if(kind==='fieldwork'){Object.assign(t,{readings:Array.from({length:9},(_,n)=>2+(n*3+i+v)%17),zones:[0,0,0,1,1,1,2,2,2],unit:i===18||i===50?'rainfall units':i===46||i===52?'household counts':i===2?'vehicle counts':'survey units'});t.brief='Investigate this fictional field dataset. Sample exactly two sites in each of three zones. Calculate each zone’s mean reading, round to a whole number and build the three bars. Different samples can give different results. Explain how your sampling choices affect the pattern.';}
 return t;
}
function gxItem(kind,i,v){const task=gxTask(kind,i,v);return {prompt:GX_TYPES[kind],answer:task.check,options:[],hint:task.brief,explanation:GEO_BANK[i].reason,geo:{kind:'gx-'+kind,source:GEO_BANK[i].source,task}};}
GEO_PACKS.forEach((p,n)=>{const i=Math.floor(n/2),j=n%2,kind=GX_PLAN[i][j],other=GX_PLAN[i][1-j];p.items=[gxItem(kind,i,j),gxItem(other===kind?'studio':other,i,j+1)];p.minutes='10–20';});
// Legacy Geography content becomes a creation brief, keeping the teacher's source and model answer.
function gxUpgradeLesson(raw){if(raw?.subject!=='geography'||!Array.isArray(raw.items))return raw;const legacy=raw.items.some(q=>!gxIs(q));if(!legacy&&Object.hasOwn(GEO_FORMATS,raw.format))return raw;const mode=FORMATS[raw.format]?.mode||'SOLO',format=Object.keys(GEO_FORMATS).find(f=>GEO_FORMATS[f].mode===mode)||'geosolo';const items=raw.items.map((q,n)=>{if(gxIs(q))return q;const evidence=String(q.geo?.source||q.explanation||q.answer||q.prompt||'Teacher source').slice(0,1800),notes=gxNotes(evidence);if(notes.length<2)notes.push(String(q.answer||q.prompt||'Explain the source').slice(0,240));const task={brief:'Create a labelled evidence sketch for this lesson: '+String(q.prompt||raw.topic).slice(0,900)+'. Place at least two evidence markers, draw two connections and add a caption. Teacher review uses the preserved model answer.',check:String(q.answer||q.explanation||'Explain the geographical relationship.').slice(0,1000),style:n%2?'storyboard':'casefile',notes:notes.slice(0,6),rubric:['Use the preserved lesson evidence.','Connect features or causes accurately.','Explain your conclusion in the caption.']};return {prompt:'Create a geographical explanation',answer:task.check,options:[],hint:task.brief,explanation:String(q.explanation||'').slice(0,1500),geo:{kind:'gx-studio',source:evidence,task}};});return {...raw,format,items};}
